def eml_fixed_point(a, b, c, x0=1.0, tol=1e-15, max_iter=10000):
    import math
    x = x0
    for i in range(max_iter):
        x_new = math.exp(a) * math.log(b * x + c)
        if abs(x_new - x) < tol:
            return x_new, i + 1
        x = x_new
    return x, max_iter

def verify_contraction(a, b, c, lo, hi):
    import math
    if b * lo + c <= 0 or b * hi + c <= 0:
        return None
    if b > 0:
        rho = abs(math.exp(a) * b / (b * lo + c))
    elif b < 0:
        rho = abs(math.exp(a) * b / (b * hi + c))
    else:
        rho = 0.0
    return rho if rho < 1 else None
